  // T69A BLOOM POST-PASS: draw the vfx canvas into a half-res offscreen WITH ctx.filter blur, then composite that back full-size additively.
  // Bright additive content bleeds soft light (the flat→luminous jump inside Canvas2D); dark content (the ground-dim) stays dark because 'lighter' of near-black adds ~0 → the dim is never brightened.
  function bloomPass(){
    if(!BLOOM_OK||!bloomOn) return;
    const bw=Math.max(1,canvas.width>>1), bh=Math.max(1,canvas.height>>1);   // half-res intermediate = quarter the pixels (perf)
    if(!bloomCv){ bloomCv=document.createElement('canvas'); bloomCx=bloomCv.getContext('2d'); }
    if(bloomCv.width!==bw||bloomCv.height!==bh){ bloomCv.width=bw; bloomCv.height=bh; }
    bloomCx.setTransform(1,0,0,1,0,0); bloomCx.globalCompositeOperation='source-over'; bloomCx.globalAlpha=1; bloomCx.clearRect(0,0,bw,bh);
    bloomCx.filter='blur('+(3*DPR).toFixed(1)+'px)';                          // 3·DPR half-res px ≈ a constant ~6 CSS-px halo at any DPR
    bloomCx.drawImage(canvas, 0,0,canvas.width,canvas.height, 0,0,bw,bh);
    bloomCx.filter='none';                                                    // T67b R2: reset filter immediately after the pass (state discipline)
    cx.setTransform(1,0,0,1,0,0); cx.globalCompositeOperation='lighter'; cx.globalAlpha=0.6; cx.imageSmoothingEnabled=true;   // T70-DIM R2: recomposite 0.5→0.6 — bloom carries the contrast the removed dim used to
    cx.drawImage(bloomCv, 0,0,bw,bh, 0,0,canvas.width,canvas.height);
    cx.globalCompositeOperation='source-over'; cx.globalAlpha=1;              // leave state clean for the next frame's top-of-frame reset
  }
  function frame(dt, now){
    const t=now/1000;
    cx.setTransform(1,0,0,1,0,0); cx.globalAlpha=1; cx.globalCompositeOperation='source-over'; cx.imageSmoothingEnabled=true; cx.clearRect(0,0,canvas.width,canvas.height);   // C2: re-assert smoothing after any context state churn
    if(tint){ tint.life-=dt; if(tint.life<=0) tint=null; else { cx.globalAlpha=tint.a*(tint.life/tint.max); cx.fillStyle=tint.color; cx.fillRect(0,0,canvas.width,canvas.height); cx.globalAlpha=1; } }
    for(let i=parts.length-1;i>=0;i--){ const p=parts[i]; p.life-=dt; if(p.life<=0){ parts.splice(i,1); continue; }
      if(p.kind==='smoke'){ p.vy+=(p.g||0)*dt; p.x+=p.vx*dt; p.y+=p.vy*dt; p.rot+=p.spin*dt; }
      else { p.vy+=p.buoy*dt; p.vx+=(p.cx0-p.x)*p.inward*dt; p.vy+=(p.cy0-p.y)*p.inward*dt; p.x+=p.vx*dt; p.y+=p.vy*dt; } }
    // PASS 1 — smoke (normal blend, expand + rotate + curl + fade-in/long-tail)
    for(const p of parts){ if(p.kind!=='smoke') continue; const age=1-p.life/p.max, sc=1+age*1.5, curl=Math.sin(age*p.curlF+p.curlP)*p.curlA, a=(age<0.1?age/0.1:1-(age-0.1)/0.9)*p.a; sprite(p.sprite, p.x+curl, p.y, p.sz*sc, p.rot, Math.max(0,a)); }
    // PASS 2 — fire glow / embers / bolts (additive)
    cx.globalCompositeOperation='lighter';
    for(const p of parts){ if(p.kind==='smoke') continue; const age=1-p.life/p.max, flick=Math.sin(t*p.flHz+p.flP)*p.flA;
      if(p.kind==='glow'){ const idx=Math.min(4,Math.floor(age*5)), sc=age<0.2?age/0.2:1-(age-0.2)/0.8*0.85; sprite(sGlow[idx], p.x+flick, p.y, p.sz*Math.max(0.1,sc), 0, Math.min(1,p.life/p.max*1.4)); }
      else sprite(sEmber, p.x+flick, p.y, p.sz, 0, Math.pow(Math.max(0,p.life/p.max),0.6)); }   // T75: cubic-in death tail (lingers then fades)
    cx.setTransform(DPR,0,0,DPR,0,0); cx.globalAlpha=1; cx.lineCap='round'; cx.lineJoin='round';
    for(let i=bolts.length-1;i>=0;i--){ const b=bolts[i]; b.life-=dt; if(b.life<=0){ bolts.splice(i,1); continue; } const a=b.life/b.max;
      for(const st of [[12,`rgba(150,190,255,${.16*a})`],[5,`rgba(205,228,255,${.5*a})`],[1.5,`rgba(255,255,255,${.95*a})`]]){ cx.lineWidth=st[0]; cx.strokeStyle=st[1]; poly(b.main); for(const br of b.branches) poly(br); } }   // T66 spectacle: bolt widths 9/3.5/1 -> 12/5/1.5 for slot-scale presence
    cx.setTransform(1,0,0,1,0,0); cx.globalCompositeOperation='source-over'; cx.globalAlpha=1;
    drawSprites(dt);   // T67 painted sprite layer (smoke source-over, kit additive) — on top of particles/bolts
    if(sprites.length||bolts.length||parts.length) bloomPass();   // T69A: bloom only when additive content exists → empty/reduced-motion frames skip it cleanly
    drawGroundDim(dt);   // T69A: dim LAST (destination-over) → behind the glow, excluded from the bloom source
    gpuTick(dt);   // T70-P0: drive the GPU overlay from the SAME loop, inside step's try/catch (one loop owns time; the T69A guarantee covers it)
  }
  function step(now){
    const rawMs=now-last;                                              // T90: raw frame time (PRE-clamp) for the jank watcher
    const dt=Math.min(0.05,(now-last)/1000); last=now;                 // T69A: dt clamp (≤50ms) + fresh last → a wake after any idle gap can't mass-expire (verified NOT the round-death cause; kept structural)
    try{ jankSample(rawMs); }catch(e){}                                // T90: match-time jank detection (gated on choreoActive inside; never throws into the loop)
    try{ frame(dt, now); }
    catch(e){}                                                         // T69A ROOT FIX: a thrown draw must NEVER kill the loop. one thrown frame used to leave raf truthy → wake() could never restart → all later-round effects dead. frame() re-clears every canvas state at its top, so a dropped frame leaks nothing.
    finally{ if(parts.length||bolts.length||tint||sprites.length||gdim||gpu.sprites.length||gpu.particles.length||gpu.hero) raf=requestAnimationFrame(step);   // ALWAYS re-arm while content lives (incl. live GPU sprites/particles/hero-moment) → raf can never get stuck truthy after a throw
             else { raf=0; try{ cx.clearRect(0,0,canvas.width,canvas.height); }catch(_){} } }
  }
  function poly(pts){ cx.beginPath(); cx.moveTo(pts[0].x,pts[0].y); for(let i=1;i<pts.length;i++) cx.lineTo(pts[i].x,pts[i].y); cx.stroke(); }
  function addFire(x,y,ang,sp,sz,life,buoy,inward){ add({ kind:'glow', x, y, vx:Math.cos(ang)*sp, vy:Math.sin(ang)*sp, buoy, inward, cx0:x, cy0:y, flHz:63+Math.random()*30, flP:Math.random()*6.28, flA:2+Math.random()*2, sz, life:life*1.6, max:life*1.6 }); }
