  // (a) CARD LANDS — warm stone dust + gold embers
  function cardLand(cxp, cyp){ if(reducedMotion()||!ready) return; const {x,y}=local(cxp,cyp), s=S();
    for(let i=0;i<Math.min(3,room());i++){ const ang=Math.random()*6.28; addSmoke(sDust, x+(Math.random()*24-12), y+6, Math.cos(ang)*16, -6-Math.random()*8, 1, 20+Math.random()*14, (1.5+Math.random()*.6)*s, .42); }
    const n=Math.min(10, 6+Math.floor(Math.random()*5), room()); for(let i=0;i<n;i++){ const ang=-Math.PI/2+(Math.random()-.5)*1.9, sp=40+Math.random()*70; addEmber(x, y+4, ang, sp, 100, .6*s, 4+Math.random()*3); } }   // T66 ambient: embers 5-8 -> 6-10
